function updateBadge(){const n=+$("badges").value,r=ranges[n];$("badgeInfo").innerHTML=`Faixa de nível: <b>${r.min}–${r.max}</b> • Nível de obediência: <b>${r.obed}</b>`}
function renderSettings(){ $("rangeSettings").innerHTML=ranges.map((r,i)=>`<div><label>${i} insígnias — nível mínimo / máximo / obediência</label><div style="display:flex;gap:5px"><input aria-label="Nível mínimo ${i}" type="number" min="1" max="100" value="${r.min}" onchange="ranges[${i}].min=+this.value;updateBadge()"><input aria-label="Nível máximo ${i}" type="number" min="1" max="100" value="${r.max}" onchange="ranges[${i}].max=+this.value;updateBadge()"><input aria-label="Obediência ${i}" type="number" min="1" max="100" value="${r.obed}" onchange="ranges[${i}].obed=+this.value;updateBadge()"></div></div>`).join("")}
