function rand(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function pick(a){return a[rand(0,a.length-1)]}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function getLevel(badge,maximum=false){const r=ranges[badge];return maximum?r.max:rand(Math.min(r.min,r.max),Math.max(r.min,r.max))}
function choosePokemon(level){return pick(POKEMON.filter(p=>p.m&&p.m.length))}
function createPoke(p,level,obedience){const hp=3+Math.floor((level-1)/10)*2;const dice=3+Math.floor((level-1)/10);
 let unlocked=(p.m||[]).filter(m=>m[0]<=level);if(!unlocked.length)unlocked=(p.m||[]).slice(0,1);
 const moves=shuffle(unlocked).slice(0,2);
 return {p,level,hp,dice,obedience,moves};}
function randomPoke(badge,maximum=false){let level=getLevel(badge,maximum);let p=choosePokemon(level);return createPoke(p,level,ranges[badge].obed)}
function pokeCard(x,index){const p=x.p;return `<article class="poke"><img class="poke-art" src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${p.n}.png" alt="${p.nm}" loading="lazy" onerror="this.onerror=null;this.src='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${p.n}.png'"><div class="dexno">#${String(p.n).padStart(3,"0")} • ${p.g?`GERAÇÃO ${p.g}`:"POKÉMON"}</div><h3>${p.nm}</h3><div class="types">${(p.t||[]).map(t=>`<span class="type">${t}</span>`).join("")}</div>
<div class="statline"><b>Nível:</b> ${x.level} / <b>Obediência:</b> ${x.obedience}</div>
<div class="statline"><b>Dados:</b> ${x.dice}d6</div><div class="statline"><b>PVs:</b> ${x.hp}</div>
<div class="hp">${Array.from({length:x.hp},(_,i)=>`<label><input type="checkbox" aria-label="PV ${i+1} de ${p.nm}"> PV ${i+1}</label>`).join("")}</div>
<div class="statline"><b>Fraquezas:</b> ${p.w||"Não informado"}</div>
<div class="statline"><b>Habilidades / golpes:</b></div>
${x.moves.map(m=>`<div class="move"><b>${m[1]}</b> (${m[2]})<br>${MOVE_DESC[m[3]]||"Descrição não disponível no HTML."}</div>`).join("")}
<div class="condition"><label for="cond-${index}">Condição</label><select id="cond-${index}">${conditions.map(c=>`<option>${c}</option>`).join("")}</select></div>
</article>`}
function showPokemon(title,team,subtitle=""){ $("resultTitle").textContent=title;$("result").innerHTML=`${subtitle?`<p class="note">${subtitle}</p>`:""}<div class="cards">${team.map(pokeCard).join("")}</div>`}
