function normalizePokemonName(value){
 return String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"")
  .toLowerCase().replace(/[’']/g,"").replace(/\s*\([^)]*\)/g,"").replace(/[^a-z0-9]/g,"");
}
function renderRegionOptions(){
 const host=$("regionOptions");
 if(!host)return;
 host.innerHTML=Object.keys(REGION_POKEMON).map(region=>
  `<label class="region-option"><input type="checkbox" name="wildRegion" value="${region}" checked><span>${region}</span></label>`
 ).join("");
}
function setAllRegions(checked){
 document.querySelectorAll('input[name="wildRegion"]').forEach(input=>input.checked=checked);
}
function getWildRegionNames(){
 const selected=[...document.querySelectorAll('input[name="wildRegion"]:checked')].map(input=>input.value);
 if(!selected.length)return null;
 const names=new Set();
 selected.forEach(region=>(REGION_POKEMON[region]||[]).forEach(name=>names.add(normalizePokemonName(name))));
 return names;
}
function choosePokemon(level,allowedNames=null){
 const eligible=POKEMON.filter(p=>p.m&&p.m.length&&(!allowedNames||allowedNames.has(normalizePokemonName(p.nm))));
 return pick(eligible.length?eligible:POKEMON.filter(p=>p.m&&p.m.length));
}
function randomWildPoke(badge,allowedNames){
 let level=getLevel(badge);
 let eligible=POKEMON.filter(p=>p.m&&p.m.length&&(!allowedNames||allowedNames.has(normalizePokemonName(p.nm))));
 let p=pick(eligible.length?eligible:POKEMON.filter(p=>p.m&&p.m.length));
 return createPoke(p,level,ranges[badge].obed);
}

function wildEncounter(){
 const b=+$("badges").value,q=+$("quantity").value;
 const selected=[...document.querySelectorAll('input[name="wildRegion"]:checked')].map(input=>input.value);
 const allowedNames=getWildRegionNames();
 const team=Array.from({length:q},()=>randomWildPoke(b,allowedNames));
 const regionLabel=selected.length?selected.join(", "):"Todas as regiões (nenhum filtro)";
 showPokemon("Encontro selvagem",team,`Insígnias: ${b} • Pokémon encontrados: ${q} • Regiões: ${regionLabel}`);
}
