const recentTrainerValues={name:[],gender:[],trait:[]};
function pickFresh(list,key,avoid=8){
 const history=recentTrainerValues[key]||[];
 const available=list.filter(v=>!history.includes(v));
 const chosen=pick(available.length?available:list);
 history.push(chosen);
 if(history.length>avoid)history.shift();
 recentTrainerValues[key]=history;
 return chosen;
}
function makeTrainer(gym=false){
 let name;
 for(let tries=0;tries<12;tries++){
  const candidate=pick(first)+" "+pick(last);
  if(!recentTrainerValues.name.includes(candidate)){name=candidate;break;}
 }
 if(!name)name=pick(first)+" "+pick(last);
 recentTrainerValues.name.push(name);
 if(recentTrainerValues.name.length>12)recentTrainerValues.name.shift();
 const gender=pickFresh(genders,"gender",3);
 const age=rand(10,80);
 const count=rand(2,6),b=+$("badges").value;
 const team=Array.from({length:count},()=>randomPoke(b,gym));
 const traitCount=rand(2,3);
 const characteristics=shuffle(traits).slice(0,traitCount);
 characteristics.forEach(t=>{recentTrainerValues.trait.push(t);if(recentTrainerValues.trait.length>12)recentTrainerValues.trait.shift();});
 return {name,gender,age,characteristics,team};
}
async function loadRandomAnimePortrait(gender=currentTrainerGender){
 currentTrainerGender=gender;
 const requestId=++trainerImageRequest;
 const img=$("trainerPortrait");
 const status=$("portraitStatus");
 if(!img)return;
 // Personagens não binários recebem um retrato aleatório de qualquer categoria.
 const category=gender==="Masculino"?"husbando":gender==="Feminino"?"waifu":pick(["waifu","husbando"]);
 img.style.display="block";
 img.removeAttribute("src");
 img.alt="Carregando retrato de anime...";
 if(status)status.textContent="Sorteando retrato...";
 try{
  // A NEKOSBEST possui categorias próprias para personagens femininas e masculinas.
  const response=await fetch(`https://nekos.best/api/v2/${category}?_=${Date.now()}`,{cache:"no-store"});
  if(!response.ok)throw new Error("A API de retratos não respondeu.");
  const data=await response.json();
  const imageUrl=data?.results?.[0]?.url;
  if(!imageUrl)throw new Error("A API não retornou uma imagem.");
  if(requestId!==trainerImageRequest)return;
  img.onload=()=>{if(requestId===trainerImageRequest&&status)status.textContent="";};
  img.onerror=()=>{if(requestId===trainerImageRequest){img.style.display="none";if(status)status.textContent="Não foi possível carregar. Clique em ‘Sortear retrato’ para tentar novamente.";}};
  img.src=imageUrl;
  img.alt=`Retrato aleatório de personagem ${category==="husbando"?"masculino":"feminino"} de anime`;
 }catch(error){
  if(requestId===trainerImageRequest){img.style.display="none";if(status)status.textContent="Não foi possível buscar o retrato. Verifique a internet e tente novamente.";}
 }
}
function trainerEncounter(){const t=makeTrainer(false);$("resultTitle").textContent="Encontro com treinador";$("result").innerHTML=trainerHTML(t,"Treinador");loadRandomAnimePortrait(t.gender);}
function gymEncounter(){const t=makeTrainer(true);$("resultTitle").textContent="Líder de ginásio";$("result").innerHTML=trainerHTML(t,"Líder de ginásio",true);loadRandomAnimePortrait(t.gender);}
function trainerHTML(t,label,gym=false){return `<div class="trainer"><div class="trainer-head"><div class="trainer-title-row"><img class="trainer-portrait" id="trainerPortrait" src="" alt="Retrato do treinador"><div class="trainer-name-block"><h3>${label}: ${t.name}</h3><div class="portrait-status" id="portraitStatus">Preparando retrato...</div><button class="secondary portrait-button" type="button" onclick="loadRandomAnimePortrait()">Sortear retrato</button></div></div><div class="meta"><span>Gênero: ${t.gender}</span><span>Idade: ${t.age} anos</span><span>Equipe: ${t.team.length} Pokémon</span></div><p><b>Características marcantes:</b> ${t.characteristics.map(c=>`<span class="trait-chip">${c}</span>`).join(" ")}</p><p class="note">${gym?`Todos os Pokémon estão no nível máximo permitido para ${$("badges").value} insígnias.`:"Treinador encontrado durante a jornada."}</p></div></div><div class="cards">${t.team.map(pokeCard).join("")}</div>`}
const places={
 "Local comum":[["Trilha tranquila","Um caminho conhecido por viajantes. Há marcas de passagem pelo chão e um pequeno espaço para descansar."],["Clareira ensolarada","Uma clareira aberta, com flores silvestres e espaço para Pokémon brincarem."],["Ponte antiga","Uma ponte de madeira cruza um riacho. Algumas tábuas rangem quando alguém passa."],["Mercadinho de estrada","Uma pequena barraca vende suprimentos e recebe viajantes de várias rotas."]],
 "Local raro":[["Jardim escondido","Um jardim isolado floresce fora de época. O lugar parece atrair Pokémon incomuns."],["Lago cristalino","A água é tão transparente que revela pedras e formas no fundo. O ambiente é silencioso."],["Ruínas esquecidas","Inscrições antigas cobrem as paredes. Há símbolos que o Mestre pode desenvolver."],["Árvore colossal","Uma árvore gigantesca domina a paisagem. Pequenos ninhos e marcas cobrem seu tronco."]],
 "Local perigoso":[["Caverna instável","O chão é irregular e o teto apresenta rachaduras. Sons ecoam por túneis desconhecidos."],["Pântano profundo","A vegetação esconde trechos de lama funda e caminhos difíceis de distinguir."],["Floresta fechada","A luz quase não atravessa as copas. É fácil perder a orientação entre as árvores."],["Desfiladeiro ventoso","Uma passagem estreita acompanha um grande desnível, com rajadas fortes e pedras soltas."]]
};
function locationEncounter(){const category=pick(Object.keys(places));const [name,desc]=pick(places[category]);$("resultTitle").textContent="Local encontrado";$("result").innerHTML=`<div class="trainer"><span class="badgelevel">${category.toUpperCase()}</span><h3 style="margin-top:10px">${name}</h3><p>${desc}</p><p class="note">O Mestre decide os acontecimentos, personagens, recompensas e desafios deste local.</p></div>`}
function itemCard(item){return `<div class="itemrow"><div><b>${item[0]}</b><div class="note">${item[1]}</div><div class="note">Pode ser usado em batalha: ${item[3]}</div></div><div class="price">${typeof item[2]==="number"?item[2]+" moedas":item[2]}</div></div>`}
function showItems(kind){let items=kind==="common"?common:kind==="rare"?rare:shuffle([...common,...rare]);let title=kind==="common"?"Itens comuns encontrados":kind==="rare"?"Itens raros encontrados":"Itens encontrados — tabela misturada";$("resultTitle").textContent=title;let amount=kind==="mixed"?rand(1,4):rand(1,3);$("result").innerHTML=`<div class="trainer"><p class="note">Resultado aleatório da tabela de itens • ${amount} ocorrência(s)</p>${Array.from({length:amount},()=>itemCard(pick(items))).join("")}</div>`}
function randomEncounter(){const choice=rand(1,3);if(choice===1)wildEncounter();else if(choice===2)trainerEncounter();else locationEncounter()}
function clearResult(){$("resultTitle").textContent="Resultado do Mestre";$("result").innerHTML='<div class="empty">Escolha um dos geradores acima para começar sua aventura!</div>'}
